INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Koordination der Beteiligten ein wichtiger Teil des Fehlermanagements?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Zusammenarbeit"}, {"text": "Nein", "correct": false, "because": "Sie ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Koordination der Beteiligten?', 3, '[{"text": "Effiziente Fehlerbehebung ermöglichen", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Projektziele neu definieren", "correct": false, "because": "Initiierungsschritt"}, {"text": "Kosten direkt senken", "correct": false, "because": "Nebenaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination synchronisiert das Team. b) Sie ist nur im Abschluss relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben umfasst die Koordination der Beteiligten?', 4, '[{"text": "Kommunikation sicherstellen", "correct": true, "because": "Fördert Austausch"}, {"text": "Unklare Anweisungen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Aufgaben verteilen", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Fortschritt abgleichen", "correct": true, "because": "Sichert Synchronisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Fehlermanagement ohne Koordination der Beteiligten effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zusammenarbeit fehlt"}, {"text": "Ja", "correct": false, "because": "Unkoordiniert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Koordination im Fehlermanagement?', 3, '[{"text": "Schnelle und effektive Fehlerbehebung", "correct": true, "because": "Fördert Ablauf"}, {"text": "Zeitplan neu erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Projekt finanzieren", "correct": false, "because": "Auftraggeberaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Koordination der Beteiligten nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Projektleiter bei der Koordination?', 3, '[{"text": "Team und Stakeholder abgleichen", "correct": true, "because": "Sichert Zusammenarbeit"}, {"text": "Projektziele allein festlegen", "correct": false, "because": "Auftraggeberaufgabe"}, {"text": "Fehler ignorieren", "correct": false, "because": "Widerspricht Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination vermeidet Doppelarbeit. b) Sie ist ohne Kommunikation möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Kommunikation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Koordination der Beteiligten?', 3, '[{"text": "Unklare Zuständigkeiten", "correct": true, "because": "Fehlende Abstimmung"}, {"text": "Fehlerbehebung wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Qualität steigt", "correct": false, "because": "Probleme bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Koordination ohne Kommunikation erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Austausch essenziell"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Koordination der Beteiligten?', 3, '[{"text": "Meeting zur Fehlerpriorisierung", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwer macht etwas", "correct": false, "because": "Zu vage"}, {"text": "Team soll allein arbeiten", "correct": false, "because": "Keine Koordination"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Koordination nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Alle Beteiligten betroffen"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind bei der Koordination wichtig?', 4, '[{"text": "Kommunikationswege", "correct": true, "because": "Fördern Abstimmung"}, {"text": "Unklare Rollen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Rollenzuweisung", "correct": true, "because": "Definiert Zuständigkeiten"}, {"text": "Regelmäßiger Austausch", "correct": true, "because": "Sichert Synchronisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Koordination dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Koordination?', 3, '[{"text": "Ticketsystem", "correct": true, "because": "Verteilt Aufgaben"}, {"text": "Keine Kommunikation", "correct": false, "because": "Fehlt Austausch"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Koordination ohne Projektleiter erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Führung nötig"}, {"text": "Ja", "correct": false, "because": "Unkoordiniert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Koordination?', 3, '[{"text": "Fehlende Kommunikation", "correct": true, "because": "Verhindert Abstimmung"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Ablauf"}, {"text": "Definierte Rollen", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Koordination verbessert Fehlerbehebung. b) Sie ist nur für technische Teams.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Koordination der Beteiligten?', 3, '[{"text": "Schnellere Problemlösung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Zusammenarbeit", "correct": false, "because": "Fördert Teamarbeit"}]');
